// Theme art generated by tools/unity_import (themes/theme_<id>)
val themePacks = rootDir.resolve("themes").listFiles { f -> f.isDirectory && f.name.startsWith("theme_") }
    ?.sortedBy { it.name }.orEmpty()

android {
    namespace = "com.funpixelnest.slots"
    compileSdk = 35

    defaultConfig {
        applicationId = "com.funpixelnest.slots"
        minSdk = 24
        targetSdk = 35
        versionCode = 1
        versionName = "1.0.0"
    }

    // Release signing: uses your keystore when SLOTS_KEYSTORE is set, otherwise the debug key
    // so the release APK can still be installed for testing.
    val keystore = System.getenv("SLOTS_KEYSTORE")?.let(::file)?.takeIf { it.exists() }
    signingConfigs {
        if (keystore != null) create("release") {
            storeFile = keystore
            storePassword = System.getenv("SLOTS_KEYSTORE_PASSWORD")
            keyAlias = System.getenv("SLOTS_KEY_ALIAS")
            keyPassword = System.getenv("SLOTS_KEY_PASSWORD")
        }
    }

    buildTypes {
        release {
            signingConfig = signingConfigs.findByName("release") ?: signingConfigs.getByName("debug")
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
        }
    }

    // Every theme ships inside the app (APK and AAB, debug and release), so all machines
    // are unlocked and playable straight from the lobby with no downloads.
    sourceSets["main"].assets.srcDirs(themePacks.map { it.resolve("src/main/assets") })

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions { jvmTarget = "17" }
    buildFeatures { compose = true }
    androidResources { noCompress += listOf("webp", "ogg", "json") }

    // Screenshot tests (Robolectric + Roborazzi) render the real Compose screens to PNGs:
    //   ./gradlew :app:testDebugUnitTest   ->  app/build/screenshots/*.png
    testOptions {
        unitTests {
            isIncludeAndroidResources = true
            all {
                it.maxHeapSize = "4g"
                it.systemProperty("roborazzi.test.record", "true")
                it.systemProperty("robolectric.graphicsMode", "NATIVE")
                it.testLogging { events("passed", "failed"); exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL }
            }
        }
    }
}

